
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_q2d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_q2d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.417108587425774e-02, -6.312796587628672e-02, -6.163243909993563e-02, -5.949143456803411e-02, -5.643343489354901e-02, -5.208364664093473e-02, -4.595040937220678e-02, -3.749513168644079e-02, -2.659595764960055e-02, -1.530095978595516e-02, -1.096494896758016e-02, -3.779805346393789e-02, -4.590656701299716e-02, -3.174839794910001e-02, -1.579098075915308e-02, -3.671671329448447e-03, -2.028103297421310e-04, -5.717554797871866e-06, -3.134490558797613e-05, 0.000000000000000e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


